//! Canonical optgroup label reflection retains actual DOMString attributes.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><select id=select><optgroup id=optgroup label=Group><option id=option label=Group value=one>One</option></optgroup><option value=two>Two</option></select><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://option-label.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn option_label_canonical_interface_descriptors_and_initial_attribute(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('option'),C=HTMLOptionElement,P=C.prototype,a=Object.getOwnPropertyDescriptor(P,'label');if(!(x instanceof C)||Object.getPrototypeOf(x)!==P||!a||!a.enumerable||!a.configurable||a.get.length!==0||a.set.length!==1||a.get.name!=='get label'||a.set.name!=='set label'||Object.hasOwn(x,'label')||x.label!=='Group'||x.firstChild.textContent!=='One')throw 'canonical option metadata';var caught=false;try{new C();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'illegal optgroup construction';"#);}
#[test]
fn option_label_exact_native_setter_aliases_and_observer_records(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('option'),a=x.getAttributeNode('label'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.label='A\ud800Z';var records=watch.takeRecords();if(x.label!=='A\ud800Z'||a.value!==x.label||x.getAttributeNode('label')!==a||records.length!==1||records[0].attributeName!=='label'||records[0].oldValue!=='Group'||x.firstChild.textContent!=='One')throw 'exact option setter';a.nodeValue='not a date';if(x.label!=='not a date'||a.value!=='not a date')throw 'label is plain reflection';x.removeAttribute('label');if(x.label!=='One'||a.ownerElement!==null||a.value!=='not a date')throw 'removed label default';"#);}
#[test]
fn option_label_conversion_reentry_abrupt_symbol_and_current_attr_identity(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('option'),old=x.getAttributeNode('label'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});var calls=0;x.label={toString:function(){calls++;x.removeAttribute('label');x.setAttribute('label','replacement');return 'A\ud800Z';}};var current=x.getAttributeNode('label'),records=watch.takeRecords();if(calls!==1||current===old||old.ownerElement!==null||old.value!=='Group'||current.value!=='A\ud800Z'||records.length!==3||records[2].oldValue!=='replacement')throw 'current real Attr after conversion';var marker={},caught;try{x.label={toString:function(){x.setAttribute('label','author effect');throw marker;}};}catch(e){caught=e;}records=watch.takeRecords();if(caught!==marker||x.label!=='author effect'||records.length!==1||records[0].oldValue!=='A\ud800Z')throw 'abrupt conversion preserves author effect';caught=false;try{x.label=Symbol('optgroup');}catch(e){caught=e instanceof TypeError;}if(!caught||watch.takeRecords().length||x.label!=='author effect')throw 'Symbol conversion refusal';for(var value of [null,undefined,0,false]){x.label=value;if(x.label!==String(value))throw 'ordinary DOMString conversion';}if(x.firstChild.textContent!=='One')throw 'metadata leaves displayed text';"#);
}


#[test]
fn option_label_absent_and_empty_attribute_have_distinct_fallback(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('option'),other=document.getElementById('select').lastChild;if(other.label!=='Two')throw 'actual absent native label';x.label='';if(x.label!==''||x.getAttribute('label')!==''||x.textContent!=='One')throw 'present empty label';x.removeAttribute('label');if(x.label!=='One'||x.hasAttribute('label'))throw 'removed native fallback';");}
#[test]
fn option_label_inert_html_aware_fallback_preserves_raw_text_and_skips_scripts_images(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=new Document(),x=owner.createElementNS('http://www.w3.org/1999/xhtml','option'),span=owner.createElementNS('http://www.w3.org/1999/xhtml','span'),script=owner.createElementNS('http://www.w3.org/1999/xhtml','script'),image=owner.createElementNS('http://www.w3.org/1999/xhtml','img');x.appendChild(owner.createTextNode(' \tA '));span.appendChild(owner.createTextNode(' \ud800\nB '));x.appendChild(span);script.appendChild(owner.createTextNode('Excluded'));x.appendChild(script);image.setAttribute('alt','Ignored');image.appendChild(owner.createTextNode('Excluded image child'));x.appendChild(image);if(!(x instanceof HTMLOptionElement)||x.label!=='A \ud800 B')throw 'actual HTML-aware raw fallback';x.label='';if(x.label!=='')throw 'present empty inert attribute';x.removeAttribute('label');if(x.label!=='A \ud800 B')throw 'restored exact inert fallback';"#);}
#[test]
fn option_label_descriptors_brands_author_override_and_saved_constructor(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('option'),C=HTMLOptionElement,P=C.prototype,a=Object.getOwnPropertyDescriptor(P,'label'),calls=0;for(var bad of [{},Object.create(P),document.body,document.createElementNS('urn:foreign','option'),new Document().createElementNS('http://www.w3.org/1999/xhtml','OPTGROUP')]){var caught=false;try{a.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'getter concrete brand';caught=false;try{a.set.call(bad,{toString:function(){calls++;return 'bad';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'brand before conversion';}Object.defineProperty(x,'label',{value:'author',writable:true,configurable:true});if(x.label!=='author'||a.get.call(x)!=='Group')throw 'canonical authority';a.set.call(x,'canonical');if(x.label!=='author'||x.getAttribute('label')!=='canonical')throw 'borrowed real setter';delete x.label;if(x.label!=='canonical'||Object.hasOwn(x,'label'))throw 'restored inherited reflection';delete window.HTMLOptionElement;if(!(x instanceof C)||Object.getPrototypeOf(x)!==P)throw 'saved original interface';"#);
}

#[test]
fn option_label_saved_child_origin_precedes_conversion_and_recovers(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('option'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var C=frame.contentWindow.HTMLOptionElement,a=Object.getOwnPropertyDescriptor(C.prototype,'label'),calls=0;if(C===HTMLOptionElement||a.get.call(x)!=='Group')throw 'captured area accessor';"#);p.set_location(&crate::navigation::address("https://other-time.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;for source in ["a.get.call(x);","a.set.call(x,{toString:function(){calls++;return 'bad';}});"]{p.begin_job();let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.set_location(&crate::navigation::address("https://option-label.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'origin precedes conversion';a.set.call(x,'recovered');if(a.get.call(x)!=='recovered')throw 'area origin recovery';");
}

// Shared reflection transactions must refuse before observable changes.

#[test]
fn option_label_writer_refusal_preserves_native_and_inert_records_and_recovers(){
 for inert in [false,true]{for source in [r"x.label='Long canonical \ud800 DateTime replacement';",r"x.setAttribute('label','Long canonical \ud800 DateTime replacement');",r"attr.value='Long canonical \ud800 DateTime replacement';",r"attr.nodeValue='Long canonical \ud800 DateTime replacement';",r"attr.textContent='Long canonical \ud800 DateTime replacement';"]{for mode in 0..5{
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','option');x.setAttribute('label','Group');"}else{"var x=document.getElementById('option');"});run(&mut d,&mut f,&mut p,"var attr=x.getAttributeNode('label'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone());let controls=f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked,format!("{:?}",c.select),c.caption.clone())).collect::<Vec<_>>();let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).expect_err(&format!("alt writer {inert}/{source}/{mode}"));assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{inert}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked,format!("{:?}",c.select),c.caption.clone())).collect::<Vec<_>>(),controls);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(attr.value!=='Group'||x.label!=='Group'||watch.takeRecords().length)throw 'atomic alt writer refusal';");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,r"var records=watch.takeRecords();if(x.label!=='Long canonical \ud800 DateTime replacement'||records.length!==1||records[0].oldValue!=='Group'||records[0].attributeName!=='label'||x.getAttributeNode('label')!==attr)throw 'fresh alt writer recovery';");
 }}}
}

#[test]
fn option_label_reads_enforce_work_copy_string_and_deadline_without_retained_growth(){
 for inert in [false,true]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();let object=if inert{run(&mut d,&mut f,&mut p,r"var time=new Document().createElementNS('http://www.w3.org/1999/xhtml','option');time.label='A\ud800Z';");let Value::Host(object)=p.runtime.execute("time;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("inert time handle")};object}else{run(&mut d,&mut f,&mut p,r"document.getElementById('option').label='A\ud800Z';");node_handle((0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("option")).unwrap())};let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.limits.host.string_bytes=1,3=>p.state.execution_deadline=Some(Instant::now()),_=>p.state.retained_limit=p.state.retained};let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.option_label_get(object);if mode==4{assert!(result.is_ok());}else{let e=result.unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("time")||e.contains("bound"),"{e}");}assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.execution_deadline=None;p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.begin_job();assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.option_label_get(object).is_ok());}}
}



#[test]
fn option_label_native_and_inert_exact_attached_aliases_and_namespace(){
 for inert in [false,true]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','option');x.setAttribute('label','Group');"}else{"var x=document.getElementById('option');"});run(&mut d,&mut f,&mut p,if inert{"var expectedRemoved='';"}else{"var expectedRemoved='One';"});run(&mut d,&mut f,&mut p,r#"var a=x.getAttributeNode('label');for(var writer of ['value','nodeValue','textContent']){a[writer]='R\ud800'+writer;if(x.label!=='R\ud800'+writer||x.getAttributeNode('label')!==a)throw 'exact attached alias';}x.setAttributeNS('urn:foreign','label','foreign');x.setAttributeNS(null,'LABEL','upper');if(x.label!=='R\ud800textContent'||x.getAttributeNodeNS(null,'label')!==a)throw 'exact null namespace/local name';x.setAttributeNS(null,'label','alternative');if(x.label!=='alternative'||a.value!==x.label)throw 'null namespace writer';x.removeAttributeNS(null,'label');if(x.label!==expectedRemoved||a.ownerElement!==null||a.value!=='alternative')throw 'removed actual alt';"#);}
}


#[test]
fn option_label_fallback_reads_refuse_atomically_and_recover_in_native_and_inert_trees(){
 for inert in [false,true]{for mode in 0..5{
  let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{r"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','option');x.appendChild(x.ownerDocument.createTextNode(' A\ud800Z '));"}else{"var x=document.getElementById('option');x.removeAttribute('label');"});
  let Value::Host(object)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("actual option")};p.state.rebuild(&d).unwrap();let tree=format!("{:?}",d.nodes);let before=(p.state.retained,p.state.dom_commits,p.state.inert_documents.backing_bytes(),p.state.attributes.len());let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.limits.host.string_bytes=1,3=>p.state.execution_deadline=Some(Instant::now()),_=>p.state.retained_limit=p.state.retained};
  let error=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.option_label_get(object).unwrap_err();assert!(error.contains("work")||error.contains("allowance")||error.contains("time")||error.contains("bound"),"{inert}/{mode}: {error}");assert_eq!(format!("{:?}",d.nodes),tree);assert_eq!((p.state.retained,p.state.dom_commits,p.state.inert_documents.backing_bytes(),p.state.attributes.len()),before);
  p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,if inert{r"if(x.label!=='A\ud800Z')throw 'fresh raw fallback read';"}else{"if(x.label!=='One')throw 'fresh native fallback read';"});
 }}
}
#[test]
fn option_label_html_aware_namespace_whitespace_and_small_output_admission(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=new Document(),x=owner.createElementNS('http://www.w3.org/1999/xhtml','option'),svg=owner.createElementNS('http://www.w3.org/2000/svg','script'),foreign=owner.createElementNS('urn:foreign','script');x.appendChild(owner.createTextNode('\tA\n'));svg.appendChild(owner.createTextNode('Excluded SVG'));x.appendChild(svg);foreign.appendChild(owner.createTextNode('Foreign'));x.appendChild(foreign);x.appendChild(owner.createComment('Excluded comment'));x.appendChild(owner.createTextNode('\r\f \u000b\u00a0\u2003 Z\t'));if(x.label!=='A Foreign \u000b\u00a0\u2003 Z')throw 'namespace and exact ASCII whitespace';var compact=owner.createElementNS('http://www.w3.org/1999/xhtml','option'),large='';for(var n=0;n<500;n++)large+=' ';compact.appendChild(owner.createTextNode(large+'A'+large));"#);
 let Value::Host(object)=p.runtime.execute("compact;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("actual compact option")};let limit=p.state.limits.host.string_bytes;p.state.limits.host.string_bytes=1;p.begin_job();let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.option_label_get(object).unwrap();assert!(matches!(result,Value::String(ref text) if text=="A"));p.state.limits.host.string_bytes=limit;assert!(!p.has_navigation_request());assert!(p.take_dynamic_scripts().is_empty()&&p.take_dynamic_stylesheets().is_empty());assert!(!p.state.images.has_changes());
}
#[test]
fn option_label_updates_native_display_and_caption_without_changing_option_state(){
 let(mut d,mut f,mut p)=fixture();let select=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("select")).unwrap();let before={let c=&f.controls[&select];let state=c.select.as_ref().unwrap();(c.value.text(),state.selected,state.options.iter().map(|o|(o.node,o.value.clone(),o.disabled,o.group)).collect::<Vec<_>>())};
 for (source,idl,display,caption) in [("document.getElementById('option').label='Ready';","Ready","Ready","Ready"),("document.getElementById('option').getAttributeNode('label').nodeValue='Alias label';","Alias label","Alias label","Alias label"),("document.getElementById('option').label='';","","One","One"),("document.getElementById('option').removeAttribute('label');","One","One","One")]{run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,&format!("if(document.getElementById('option').label!=='{idl}')throw 'actual label getter';"));let c=&f.controls[&select];let state=c.select.as_ref().unwrap();assert_eq!(state.options[0].label,display);assert_eq!(c.caption,caption);assert_eq!((c.value.text(),state.selected,state.options.iter().map(|o|(o.node,o.value.clone(),o.disabled,o.group)).collect::<Vec<_>>()),before);}
}
#[test]
fn option_label_native_display_bound_stable_storage_and_payload_refusal(){
 let(mut d,mut f,mut p)=fixture();let select=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("select")).unwrap();run(&mut d,&mut f,&mut p,"var x=document.getElementById('option'),longA='',longB='';for(var i=0;i<300;i++){longA+='a';longB+='b';}x.label=longA;");let retained=p.state.retained;
 for _ in 0..4{p.begin_job();run(&mut d,&mut f,&mut p,"x.label=longB;if(x.label.length!==300)throw 'exact full option label';");assert_eq!(p.state.retained,retained);let c=&f.controls[&select];assert_eq!(c.select.as_ref().unwrap().options[0].label,"b".repeat(256));assert_eq!(c.caption,"b".repeat(256));}
 let old=std::mem::replace(&mut f.controls.get_mut(&select).unwrap().select.as_mut().unwrap().options[1].label,"z".repeat(128*1024));let tree=format!("{:?}",d.nodes);let native=format!("{:?}",f.controls[&select].select);let caption=f.controls[&select].caption.clone();let before=(p.state.retained,p.state.dom_commits);p.begin_job();let error=p.runtime.execute("x.label='refused';",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("128 KiB"),"{error}");assert_eq!(format!("{:?}",d.nodes),tree);assert_eq!(format!("{:?}",f.controls[&select].select),native);assert_eq!(f.controls[&select].caption,caption);assert_eq!((p.state.retained,p.state.dom_commits),before);
 f.controls.get_mut(&select).unwrap().select.as_mut().unwrap().options[1].label=old;p.begin_job();run(&mut d,&mut f,&mut p,"x.label='recovered';if(x.label!=='recovered')throw 'native option payload recovery';");
}

#[test]
fn option_label_unselected_updates_preserve_current_caption_and_empty_selection(){
 let(mut d,mut f,mut p)=fixture();let select=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("select")).unwrap();
 run(&mut d,&mut f,&mut p,"var select=document.getElementById('select'),first=document.getElementById('option'),second=select.lastChild;second.label='Much longer unselected label';");assert_eq!(f.controls[&select].caption,"Group");assert_eq!(f.controls[&select].value.text(),"one");
 run(&mut d,&mut f,&mut p,"select.selectedIndex=1;first.label='Longest label on the unselected first option';");assert_eq!(f.controls[&select].caption,"Much longer unselected label");assert_eq!(f.controls[&select].value.text(),"two");
 run(&mut d,&mut f,&mut p,"second.label='';");assert_eq!(f.controls[&select].caption,"Two");
 run(&mut d,&mut f,&mut p,"select.selectedIndex=-1;first.label='No selected caption';");assert_eq!(f.controls[&select].caption,"");assert_eq!(f.controls[&select].value.text(),"");assert_eq!(f.controls[&select].select.as_ref().unwrap().selected,None);
}
